#include <vector>
#include <memory>

// Standard allocators (like std::allocator<T>) are trivially interchangeable.

int main() {
    std::vector<int, std::allocator<int>> v1;
    std::vector<int, std::allocator<int>> v2;

    // Storage allocated by v1's allocator instance can be deallocated 
    // by v2's allocator instance if they were swapped or merged (conceptually).

    v1.push_back(10);
    v2.push_back(20);
    v1.swap(v2); // Requires allocator interchangeability (or propagation rules)
}
